import { ScatterChart, useScatterChart } from '@dreadnought/ui/react';
const series=[{id:'a',label:'A',data:[{id:'one',label:'One',x:2,y:4,size:25}]}];
function Summary(){const {visible}=useScatterChart();return <p>Видимых: {visible.length}</p>;}
export function Example(){return <ScatterChart label="Данные" series={series} xDomain={[0,10]} yDomain={[0,10]}><Summary/><ScatterChart.Legend>{({defaultContent})=><span>{defaultContent}</span>}</ScatterChart.Legend><ScatterChart.Plot tooltipContent={({defaultContent})=><div>{defaultContent}</div>}>{({defaultContent})=>defaultContent}</ScatterChart.Plot><ScatterChart.Empty/><ScatterChart.Table/><ScatterChart.Pagination/></ScatterChart>;}
